{
  "findings": [
    {
      "check_id": "CKV_GCP_106",
      "title": "Ensure Google compute firewall ingress does not allow unrestricted HTTP port 80 access",
      "resource": "google_compute_firewall.allow_http",
      "severity": "MEDIUM",
      "explanation": "Allowing unrestricted access to port 80 from all IPs (0.0.0.0/0) exposes the service to potential attacks from any source. Restricting the source IP range or using HTTPS (port 443) exclusively would mitigate this risk."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http\" {\n  name    = \"digital-library-content-management-platform-firewall-http\"\n  network = google_compute_network.digital_library_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"80\", \"443\"]\n  }\n  source_ranges = [\"192.168.0.0/16\"] # Restricting access to a private IP range\n  target_tags   = [\"http-server\"]\n}",
  "fix_summary": "Restricted the source_ranges from 0.0.0.0/0 to 192.168.0.0/16 to limit access to a private IP range, reducing the risk of unrestricted public exposure."
}
